-- PT101-S3-Q2
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND q.stimulus=$batch01$Advertisement: Anyone who thinks moisturizers are not important for beautiful skin should consider what happens to the earth, the skin of the world, in time of drought. Without regular infusions of moisture the ground becomes lined and cracked and its lush liveliness fades away. Thus your skin, too, should be protected from the ravages caused by lack of moisture; give it the protection provided by regular infusions of Dewyfresh, the drought-defying moisturizer.$batch01$ AND q.prompt=$batch01$The Dewyfresh advertisement exhibits which one of the following errors of reasoning?$batch01$ AND q.correct_choice=$batch01$E$batch01$) THEN RAISE EXCEPTION 'Question changed: PT101-S3-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S3-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It treats something that is necessary for bringing about a state of affairs as something that is sufficient to bring about that state of affairs.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT101-S3-Q2 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It treats the fact that two things regularly occur together as proof that there is a single thing that its the cause of them both.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT101-S3-Q2 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It overlooks the fact that changing what people think is the case does not necessarily change what is the case.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT101-S3-Q2 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It relies on the ambiguity of the term “infusion, ” which can designate either a process or the product of that process.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT101-S3-Q2 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$It relies on an analogy between two things that are insufficiently alike in the respects in which they would have to be alike for the conclusion to be supported.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT101-S3-Q2 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT101-S3-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion (thus)$batch01$, $batch01$Skin should get regular Dewyfresh moisturizer to protect it from damage caused by lack of moisture.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Drought dries and cracks the earth, which the advertisement calls “the skin of the world.”$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Given that dry ground cracks, how could skin still behave differently? Soil and human skin are different materials. The ad needs the two to resemble each other in the very process it is comparing. The phrase “skin of the world” is a metaphor, not evidence that a moisturizer affects skin the way rain affects soil. Even if skin needs moisture, nothing here establishes that Dewyfresh provides the promised protection.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Look for a criticism of an analogy between the earth and human skin that has not established the relevant similarity.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Necessary versus sufficient would require the ad to argue, for example, that because moisture is required for healthy skin, applying Dewyfresh guarantees beautiful skin. It does not make that formal move. Its evidence is the earth analogy.$batch01$), ($batch01$B$batch01$, $batch01$A common cause would explain why two observed events happen together. The ad does not report two correlated events and infer a shared cause. It compares two different things.$batch01$), ($batch01$C$batch01$, $batch01$The argument does not claim that changing beliefs changes physical reality. The opening addresses people who doubt moisturizers, but the evidence is about drought, not a change in what people believe.$batch01$), ($batch01$D$batch01$, $batch01$“Infusion” is used to mean an input of moisture in both places. The conclusion does not switch from a process to its product. The questionable switch is from ground to human skin.$batch01$), ($batch01$E$batch01$, $batch01$Test the analogy's relevant feature. Dry soil cracks without water; does human skin respond to a moisturizer in the same way? The ad gives no reason to think so. Calling earth “skin” makes the analogy memorable but does not supply the biological similarity the conclusion needs.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
